package ktanesolver.module.modded.regular.snooker;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service @ModuleInfo(type=ModuleType.SNOOKER,id="snooker",name="Snooker",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Find a legal four-break potting sequence that clears the table at the displayed target scores.",tags={"snooker","balls","scores","sequence","search"})public class SnookerSolver extends AbstractModuleSolver<SnookerInput,SnookerOutput>{private static final String[]COLORS={"","red","yellow","green","brown","blue","pink","black"};private record State(int reds,boolean clearance,boolean redNext,int nextColor){}private record Shot(String color,int points,State state){}
 @Override protected SolveResult<SnookerOutput>doSolve(RoundEntity r,BombEntity b,ModuleEntity m,SnookerInput i){if(i==null||i.redCount()<8||i.redCount()>10||i.targetBreaks()==null||i.targetBreaks().size()!=4||i.targetBreaks().stream().anyMatch(x->x==null||x<1))return failure("Enter 8 to 10 reds and four positive target breaks");List<List<String>>result=new ArrayList<>();if(!solveBreak(0,new State(i.redCount(),false,true,2),i.targetBreaks(),result))return failure("No legal four-break clearance matches those targets; recheck the display");List<String>actions=result.stream().flatMap(List::stream).toList();storeState(m,"snookerReds",i.redCount());return success(new SnookerOutput(result,actions));}
 private static boolean solveBreak(int stage,State state,List<Integer>targets,List<List<String>>result){List<String>shots=new ArrayList<>();return play(stage,state,0,targets.get(stage),targets,result,shots);}
 private static boolean play(int stage,State state,int score,int target,List<Integer>targets,List<List<String>>result,List<String>shots){if(score==target){boolean cleared=state.reds()==0&&state.clearance()&&state.nextColor()==8;if(stage==3){if(!cleared)return false;List<String>done=new ArrayList<>(shots);done.add("cue");result.add(done);return true;}State next=state.reds()==0&&!state.clearance()?new State(0,true,false,2):state.reds()>0?new State(state.reds(),false,true,2):state;List<String>done=new ArrayList<>(shots);done.add("cue");result.add(done);if(solveBreak(stage+1,next,targets,result))return true;result.removeLast();return false;}for(Shot shot:shots(state)){if(score+shot.points()>target)continue;shots.add(shot.color());if(play(stage,shot.state(),score+shot.points(),target,targets,result,shots))return true;shots.removeLast();}return false;}
 private static List<Shot>shots(State s){if(s.clearance())return s.nextColor()>7?List.of():List.of(new Shot(COLORS[s.nextColor()],s.nextColor(),new State(0,true,false,s.nextColor()+1)));if(s.redNext())return s.reds()>0?List.of(new Shot("red",1,new State(s.reds()-1,false,false,2))):List.of();List<Shot>out=new ArrayList<>();for(int c=2;c<=7;c++)out.add(new Shot(COLORS[c],c,s.reds()==0?new State(0,true,false,2):new State(s.reds(),false,true,2)));return out;}
}
